package com.aetherforge.repo;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.util.*;
@Repository public class QualityRepository {private final JdbcTemplate db;public QualityRepository(JdbcTemplate db){this.db=db;}public void save(String productId,String result,double confidence,String method,String version,String imageName,String defects){String id=UUID.randomUUID().toString();db.update("insert into quality_inspection(id,factory_id,product_id,result,confidence,method,model_version,image_name) values(?,'00000000-0000-0000-0000-000000000001',?,?,?,?,?,?)",id,productId,result,confidence,method,version,imageName);if(defects!=null)for(String d:defects.split(","))if(!d.isBlank())db.update("insert into quality_defect(inspection_id,category,confidence) values(?,?,?)",id,d.trim(),confidence);}public List<Map<String,Object>> list(){return db.queryForList("select qi.*,coalesce(string_agg(qd.category,', '),'') defects from quality_inspection qi left join quality_defect qd on qd.inspection_id=qi.id group by qi.id order by inspected_at desc limit 100");}}
